package thaumcraft.verification;
import net.minecraft.client.*;import net.minecraft.world.item.*;import net.minecraft.world.phys.*;import thaumcraft.registry.*;import thaumcraft.client.*;
final class MechanicsReviewClient {
 static int zapSounds,bolts,maxBubbles;static boolean installed;
 static void install(){if(installed)return;installed=true;net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.client.event.sound.PlaySoundEvent e)->{if(PhotoLiveClient.scene==108&&e.getSound()!=null&&e.getSound().getLocation().equals(R2Sounds.ZAP.get().getLocation()))zapSounds++;});}
 static Object field(Object owner,Class<?> type,String name)throws Exception{return FollowupReviewClient.field(owner,type,name);}
 static int particles(String name)throws Exception{var mc=Minecraft.getInstance();var map=(java.util.Map<?,?>)field(mc.particleEngine,net.minecraft.client.particle.ParticleEngine.class,"particles");int total=0;for(var queue:map.values())for(var p:(java.util.Collection<?>)queue)if(p.getClass().getName().contains(name))total++;return total;}
 static void tick(int scene,int age)throws Exception {var mc=Minecraft.getInstance();install();if(age==1)maxBubbles=0;if(age>=20&&age<=60)maxBubbles=Math.max(maxBubbles,particles("CrucibleEffects$Bubble"));
  if(scene==100&&age==43&&mc.player.isDeadOrDying())mc.player.respawn();
  if(scene==114&&age==60)PhotoLiveClient.check((Integer)field(null,RunicShieldHud.class,"maximum")==0,"native runic HUD clears when gear is removed without death");
  if(scene==100&&age==72){PhotoLiveClient.check(mc.player.isAlive(),"native client has completed death and respawn");PhotoLiveClient.check((Integer)field(null,RunicShieldHud.class,"maximum")==0&&(Integer)field(null,RunicShieldHud.class,"charge")==0,"real runic HUD is cleared after death and gear loss");}
  if(scene==92&&age==60){PhotoLiveClient.check(mc.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(PhotoLiveScene.O),"native crosshair can target energized node while charger is active");var n=(thaumcraft.visnet.EnergizedNodeBlockEntity)mc.level.getBlockEntity(PhotoLiveScene.O);PhotoLiveClient.check(n.capacity().size()==6&&n.capacity().values().stream().allMatch(v->v==4),"client receives all six energized aspect capacities");PhotoLiveClient.check((Float)field(null,GogglesAspectOverlay.class,"tagScale")>0,"actual energized aspect overlay is rendering");}
  if((scene>=93&&scene<=95||scene>=103&&scene<=107||scene==112||scene==113)&&age==60){var c=(thaumcraft.production.CrucibleBlockEntity)mc.level.getBlockEntity(PhotoLiveScene.O);if(scene==95)PhotoLiveClient.check(c.water()==0&&c.store.amount()==0,"wand empty action synchronizes to native client");else{PhotoLiveClient.check(mc.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(PhotoLiveScene.O),"native crosshair selects crucible interior at water level, scene="+scene);int bubbles=particles("CrucibleEffects$Bubble");PhotoLiveClient.check(scene==93||scene==113?bubbles==0:scene==112?maxBubbles>0:bubbles>0,"native crucible bubble particles match heat and water, scene="+scene+", count="+bubbles);if(c.store.amount()>0)PhotoLiveClient.check((Float)field(null,GogglesAspectOverlay.class,"tagScale")>0,"native goggles display crucible aspects, scene="+scene);}}
  if(scene==96&&age==35)PhotoLiveClient.check(mc.screen instanceof FocalManipulatorScreen,"actual focal manipulator GUI is open for alpha-border verification");
  if((scene==101||scene==102||scene==111)&&age==60){if(scene==111){var armored=mc.level.getEntitiesOfClass(thaumcraft.entities.CultistLeader.class,new AABB(PhotoLiveScene.O).inflate(8)).getFirst();PhotoLiveClient.check(!armored.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.HEAD).isEmpty()&&!armored.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.CHEST).isEmpty(),"sword grip is verified with actual full Praetor armor");}var item=new ItemStack(R5Content.CRIMSON_SWORD.get());var model=mc.getItemRenderer().getModel(item,mc.level,mc.player,0);var vanilla=mc.getItemRenderer().getModel(new ItemStack(Items.DIAMOND_SWORD),mc.level,mc.player,0);for(var context:new ItemDisplayContext[]{ItemDisplayContext.THIRD_PERSON_RIGHT_HAND,ItemDisplayContext.FIRST_PERSON_RIGHT_HAND}){var a=model.getTransforms().getTransform(context);var b=vanilla.getTransforms().getTransform(context);PhotoLiveClient.check(a.rotation.equals(b.rotation)&&a.translation.equals(b.translation)&&a.scale.equals(b.scale),"crimson sword uses native player sword grip: "+context);}var leaders=mc.level.getEntitiesOfClass(thaumcraft.entities.CultistLeader.class,new AABB(PhotoLiveScene.O).inflate(8));var renderer=(CultistRenderer<?>)mc.getEntityRenderDispatcher().getRenderer(leaders.getFirst());PhotoLiveClient.check(renderer.getModel().rightArmPose==net.minecraft.client.model.HumanoidModel.ArmPose.ITEM,"praetor raises the held sword arm like a player");}
  if(scene==108&&age==20){zapSounds=0;bolts=0;}if(scene==108&&age>=25&&age<=70)bolts=Math.max(bolts,particles("LegacyLightningParticle"));if(scene==108&&age==72){PhotoLiveClient.check(bolts>=2,"real bullying packets create both native lightning passes");PhotoLiveClient.check(zapSounds>=4,"real bullying packets play original zap sound: "+zapSounds);}
 }
}
